import re

HELPER_FUNC = '''

def _chat_template_kwargs(tokenizer):
    name = getattr(tokenizer, 'name_or_path', '').lower()
    if 'qwen' in name:
        return {'enable_thinking': False}
    return {}

'''

files = [
    '/root/schema_semantic_constrained_ie/run_extraction.py',
    '/root/schema_semantic_constrained_ie/run_extraction_docred.py',
    '/root/schema_semantic_constrained_ie/run_constrained_extraction.py',
]

for fpath in files:
    with open(fpath, 'r') as f:
        content = f.read()

    content = content.replace(
        ', enable_thinking=False',
        ', **_chat_template_kwargs(tokenizer)'
    )
    content = re.sub(
        r'\n(\s+)enable_thinking=False,',
        r'\n\1**_chat_template_kwargs(tokenizer),',
        content
    )

    if '_chat_template_kwargs' not in content:
        patterns_to_find = [
            '\nENTITY_TYPES',
            '\nRAW_TO_CANONICAL',
        ]
        insert_pos = None
        for pat in patterns_to_find:
            pos = content.find(pat)
            if pos != -1:
                if insert_pos is None or pos < insert_pos:
                    insert_pos = pos
        if insert_pos is not None:
            content = content[:insert_pos] + HELPER_FUNC + content[insert_pos:]

    with open(fpath, 'w') as f:
        f.write(content)
    print(f'Patched: {fpath}')
"
